/// <summary>
/// ADO#89454, CB518, Financial dimension deviations, LalitJ, 16-Oct-2023
/// </summary>
[ExtensionOf(tableStr(LedgerJournalTrans))]
final class METLedgerJournalTrans_Table_Extension
{
}

Method.Source:
    /// <summary>
    /// The method indicates the additional logic to be called when a field of journal line is modified
    /// </summary>
    /// <param name = "_fieldId">
    /// The actual field being modified
    /// </param>
    public void modifiedField(FieldId _fieldId)
    {
        DimensionDefault    mergedDimensions,currentDimensions;
        LedgerJournalTable  ledgerJournalTable;
        LedgerJournalName   ledgerJournalName;
        LedgerJournalTrans  ledgerJournalTransExist;

        next modifiedField(_fieldId);

        switch(_fieldId)
        {
            case fieldNum(LedgerJournalTrans,OffsetLedgerDimension):                

                ledgerJournalTable          = this.ledgerJournalTable();
                ledgerJournalName           = LedgerJournalName::find(ledgerJournalTable.JournalName);

                if(ledgerJournalName.METCopyDimensions == NoYes::Yes)
                {
                    //When financial dimensions of offset account are populated   
                    if(this.OffsetLedgerDimension && this.OffsetAccountType == LedgerJournalACType::Ledger && this.AccountType == LedgerJournalACType::Vend)
                    {
                        mergedDimensions            = LedgerDimensionFacade::getDefaultDimensionFromLedgerDimension(this.OffsetLedgerDimension);
                        this.DefaultDimension       = mergedDimensions;
                    }
                }
                break;

            case fieldNum(LedgerJournalTrans,LedgerDimension):                

                ledgerJournalTable          = this.ledgerJournalTable();
                ledgerJournalName           = LedgerJournalName::find(ledgerJournalTable.JournalName);

                if(ledgerJournalName.METCopyDimensions == NoYes::Yes)
                {
                    //Case 1 - Current line is of Ledger type and existing Vendor type line needs to be found and updated within same voucher
                    if(this.AccountType == LedgerJournalACType::Ledger && !this.OffsetLedgerDimension)
                    {
                        METCopyDimensionMethods::updateDimensionsForMainAccount(this);
                    }

                    //Case 2 - Current line is of Vendor type and existing ledger line needs to be found within same voucher
                    else
                    {
                        if(this.AccountType == LedgerJournalACType::Vend && !this.OffsetLedgerDimension)
                        {
                            this.DefaultDimension = METCopyDimensionMethods::getDimensionsFromMainAccountModified(this);
                        }
                    }
                }
                break;
        }
    }

    /// <summary>
    /// This method will be called when an insert would be made on journal lines
    /// </summary>
    public void insert()
    {
        DimensionDefault    mergedDimensions,currentDimensions;
        LedgerJournalTable  ledgerJournalTable;
        LedgerJournalName   ledgerJournalName;
        LedgerJournalTrans  ledgerJournalTransExist;

        ledgerJournalTable          = this.ledgerJournalTable();
        ledgerJournalName           = LedgerJournalName::find(ledgerJournalTable.JournalName);

        // Custom field added on journal name master setup to check if dimensions needs to be copied
        if(ledgerJournalName.METCopyDimensions == NoYes::Yes)
        {
            //Case 1 - When financial dimensions of offset account are populated
            if(this.OffsetLedgerDimension && this.OffsetAccountType == LedgerJournalACType::Ledger && this.AccountType == LedgerJournalACType::Vend)
            {
                mergedDimensions            = LedgerDimensionFacade::getDefaultDimensionFromLedgerDimension(this.OffsetLedgerDimension);
                this.DefaultDimension       = mergedDimensions;
            }

            else
            {
                //Case 2 - Current line is of Ledger type and existing Vendor type line needs to be found within same voucher
                if(this.AccountType == LedgerJournalACType::Ledger && !this.OffsetLedgerDimension)
                {
                    METCopyDimensionMethods::updateDimensionsForMainAccount(this);
                }

                //Case 3 - Current line is of Vendor type and existing ledger line needs to be found within same voucher
                else
                {
                    if(this.AccountType == LedgerJournalACType::Vend && !this.OffsetLedgerDimension)
                    {   
                        this.DefaultDimension = METCopyDimensionMethods::getDimensionsFromMainAccountModified(this);                        
                    }
                }
            }
            
        }

        next insert();
    }
